package com.dario.jarvis;
public class CommandTest {public static void main(String[] args){for(String name:new String[]{"true caller","true cooler","tru caller","Truecaller"})if(!Command.appName(name).equals("truecaller"))throw new AssertionError(name);if(!Command.body("Jarvis, abre Truecaller").equals("abre truecaller"))throw new AssertionError("prefix");if(!Command.body("Jarvis, recuerda que mañana tomo café").equals("recuerda que manana tomo cafe"))throw new AssertionError("accents");if(!Command.appName("la aplicación Gmail").equals("gmail"))throw new AssertionError("app prefix");System.out.println("Command aliases passed");}}
